package com.aditya.day14.room; import jakarta.persistence.*; import java.util.UUID; @Entity public class Room { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; String name; String owner; public UUID getId(){return id;} public String getName(){return name;} public void setName(String x){name=x;} public String getOwner(){return owner;} public void setOwner(String x){owner=x;} }
